OPENQASM 2.0;
include "qelib1.inc";
// Grover search on 3 qubits for |101>: two rounds of oracle + diffuser.
qreg q[3];
creg c[3];
h q;
// round 1: oracle flips the sign of |101>
x q[1];
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q[1];
// diffuser
h q;
x q;
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q;
h q;
// round 2
x q[1];
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q[1];
h q;
x q;
h q[2];
ccx q[0],q[1],q[2];
h q[2];
x q;
h q;
measure q -> c;

OPENQASM 2.0;
include "qelib1.inc";
// Superpose every 4th basis state, then the QFT: the outcomes are the multiples of 2^4/4.
qreg q[4];
creg c[4];
h q[2];
h q[3];
h q[3];
cp(pi/2) q[3],q[2];
cp(pi/4) q[3],q[1];
cp(pi/8) q[3],q[0];
h q[2];
cp(pi/2) q[2],q[1];
cp(pi/4) q[2],q[0];
h q[1];
cp(pi/2) q[1],q[0];
h q[0];
swap q[0],q[3];
swap q[1],q[2];
measure q -> c;
